<?php
require __DIR__.'/../vendor/autoload.php';
$cfg=[];foreach(file(__DIR__.'/../.env') as $l)if(preg_match('/^\s*([\w.]+)\s*=\s*(.*?)\s*$/',$l,$m))$cfg[$m[1]]=trim($m[2],"\"'");
$db=new PDO('mysql:host='.($cfg['database.default.hostname']??'127.0.0.1').';dbname='.($cfg['database.default.database']??'portal_bairro').';charset=utf8mb4',$cfg['database.default.username']??'root',$cfg['database.default.password']??'root',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$dir=__DIR__.'/../writable/backups/prd-'.date('Ymd-His');mkdir($dir,0700,true);$f=fopen($dir.'/banco.sql','wb');fwrite($f,"SET FOREIGN_KEY_CHECKS=0;\n");
$counts=[];foreach($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $t){$counts[$t]=(int)$db->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();$ddl=$db->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM)[1];fwrite($f,"DROP TABLE IF EXISTS `$t`;\n$ddl;\n");foreach($db->query("SELECT * FROM `$t`",PDO::FETCH_ASSOC) as $row){$vals=array_map(fn($v)=>$v===null?'NULL':$db->quote((string)$v),array_values($row));$cols=implode(',',array_map(fn($v)=>"`$v`",array_keys($row)));fwrite($f,"INSERT INTO `$t` ($cols) VALUES (".implode(',',$vals).");\n");}}
fwrite($f,"SET FOREIGN_KEY_CHECKS=1;\n");fclose($f);file_put_contents($dir.'/contagens.json',json_encode($counts,JSON_PRETTY_PRINT));echo json_encode(['backup'=>$dir,'contagens'=>$counts,'portais'=>$db->query('SELECT id,nome,identificador,limite_anuncios FROM portais')->fetchAll(PDO::FETCH_ASSOC),'anuncios'=>$db->query('SELECT id,nome,situacao FROM anuncios')->fetchAll(PDO::FETCH_ASSOC)],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);
